class Solution {
public:
    int findKthNumber(int m, int n, int k) {
        auto countLessOrEqual = [&](int x) {
            int cnt = 0;
            for (int i = 1; i <= m; i++) {
                cnt += min(n, x / i);
            }
            return cnt;
        };
        int low = 1, high = m * n;
        while (low < high) {
            int mid = low + (high - low) / 2;
            if (countLessOrEqual(mid) >= k) high = mid;
            else low = mid + 1;
        }
        return low;
    }
};

class Solution {
    public int findKthNumber(int m, int n, int k) {
        int low = 1, high = m * n;
        while (low < high) {
            int mid = low + (high - low) / 2;
            int cnt = 0;
            for (int i = 1; i <= m; i++) {
                cnt += Math.min(n, mid / i);
            }
            if (cnt >= k) high = mid;
            else low = mid + 1;
        }
        return low;
    }
}

var findKthNumber = function(m, n, k) {
    let low = 1, high = m * n;
    while (low < high) {
        const mid = Math.floor((low + high) / 2);
        let cnt = 0;
        for (let i = 1; i <= m; i++) {
            cnt += Math.min(n, Math.floor(mid / i));
        }
        if (cnt >= k) high = mid;
        else low = mid + 1;
    }
    return low;
};
